// @appbuilder-oauth-v4
// AUTO-GENERATED by setup_oauth. Edit with care -- the LLM may regenerate.

import { createContext, useCallback, useEffect, useState, type ReactNode } from "react";
import { api } from "@/lib/api";
import { signInWithPopup } from "./auth-popup";

/** Set after explicit sign-out so dev auto-login does not immediately bounce back in. */
const SKIP_DEV_AUTO_KEY = "stocktag_skip_dev_auto";

export type AuthUser = {
  id: string;
  email: string | null;
  name: string | null;
  picture: string | null;
  provider: string;
};

export type AuthContextValue = {
  user: AuthUser | null;
  status: "loading" | "authenticated" | "anonymous" | "error";
  signIn: (providerId: string, scopes?: string) => Promise<void>;
  signInDev: (email: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
  refresh: () => Promise<void>;
};

export const AuthContext = createContext<AuthContextValue | null>(null);

async function fetchMe(): Promise<AuthUser | null> {
  const resp = await fetch("/api/auth/me", { credentials: "include" });
  if (!resp.ok) return null;
  const json = (await resp.json()) as { user: AuthUser | null };
  return json.user ?? null;
}

/**
 * When Vite dev (`import.meta.env.DEV`) and the server has dev login enabled
 * (`NODE_ENV=development` / not Vercel production), mint a session for the
 * dedicated local account without a password prompt.
 */
async function tryDevAutoLogin(): Promise<AuthUser | null> {
  if (!import.meta.env.DEV) return null;
  try {
    if (sessionStorage.getItem(SKIP_DEV_AUTO_KEY) === "1") return null;
  } catch {
    // sessionStorage may be unavailable; still attempt auto-login.
  }

  const resp = await fetch("/api/auth/dev-login", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ auto: true }),
  });
  // 404 = production / dev login disabled — leave anonymous.
  if (!resp.ok) return null;
  const json = (await resp.json().catch(() => ({}))) as { user?: AuthUser | null };
  return json.user ?? (await fetchMe());
}

/**
 * Idempotent demo inventory seed for local/dev only.
 * Server rejects outside isDevAuthEnabled(); skips when consumables already exist.
 */
async function tryDevAutoSeed(): Promise<void> {
  if (!import.meta.env.DEV) return;
  try {
    await api.post("/api/seed", {});
  } catch {
    // Ignore — Admin still offers "Load sample data" in DEV.
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [status, setStatus] = useState<AuthContextValue["status"]>("loading");

  const refresh = useCallback(async () => {
    try {
      const me = await fetchMe();
      setUser(me);
      setStatus(me ? "authenticated" : "anonymous");
    } catch {
      setUser(null);
      setStatus("error");
    }
  }, []);

  const signIn = useCallback(async (providerId: string, scopes?: string) => {
    await signInWithPopup(providerId, scopes);
    await refresh();
  }, [refresh]);

  const signInDev = useCallback(async (email: string, password: string) => {
    const resp = await fetch("/api/auth/dev-login", {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    const json = (await resp.json().catch(() => ({}))) as {
      error?: string;
      code?: string;
    };
    if (!resp.ok) {
      throw new Error(json.error || "Development sign-in failed.");
    }
    try {
      sessionStorage.removeItem(SKIP_DEV_AUTO_KEY);
    } catch {
      // ignore
    }
    await tryDevAutoSeed();
    await refresh();
  }, [refresh]);

  const signOut = useCallback(async () => {
    // Stay signed out for this tab until a manual dev login or full browser restart.
    try {
      sessionStorage.setItem(SKIP_DEV_AUTO_KEY, "1");
    } catch {
      // ignore
    }
    await fetch("/api/auth/logout", { method: "POST", credentials: "include" });
    setUser(null);
    setStatus("anonymous");
  }, []);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        let me = await fetchMe();
        if (!me) {
          me = await tryDevAutoLogin();
        }
        if (me) {
          await tryDevAutoSeed();
        }
        if (cancelled) return;
        setUser(me);
        setStatus(me ? "authenticated" : "anonymous");
      } catch {
        if (cancelled) return;
        setUser(null);
        setStatus("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return <AuthContext.Provider value={{ user, status, signIn, signInDev, signOut, refresh }}>{children}</AuthContext.Provider>;
}
